@orders_bp.route("/<int:order_id>", methods=["GET"])
@require_auth
def get_order(order_id: int):
    session = get_session()
    order = session.get(Order, order_id)
    if order is None:
        return jsonify({"error": "not found"}), 404
    if not is_owner_or_admin(g.current_user, order.user_id):
        return jsonify({"error": "forbidden"}), 403
    return jsonify(order.to_dict())

def is_owner_or_admin(user: User, owner_id: int) -> bool:
    """Ownership check used for per-object access (orders, profiles)."""
    return user.id == owner_id or user.role == "admin"

def require_auth(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        user = get_current_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        g.current_user = user
        return fn(*args, **kwargs)
    return wrapper
